-- ====================================================================
-- Re-Import swiss_location mit Ortschaftsname (Walter 29.07.2026)
-- Quelle: swisstopo AMTOVZ_CSV_WGS84 (aktueller Download)
--
-- Problem bisher: nur politische Gemeinde (plz4+bfs) — Post-Ortschaften
-- wie «Bützberg» (PLZ 4922) fehlten. Adress-Ort muss Ortschaft sein.
--
-- In TablePlus ausführen (ganzer Block).
-- ====================================================================

BEGIN;

ALTER TABLE swiss_location
    ADD COLUMN IF NOT EXISTS ortschaftsname VARCHAR(80);

-- Alte Unique (plz4, bfs_nr) → neu (plz4, ortschaftsname)
ALTER TABLE swiss_location
    DROP CONSTRAINT IF EXISTS swiss_location_plz_bfs_unique;

TRUNCATE swiss_location RESTART IDENTITY;

