UPDATE swiss_location SET ortschaftsname = gemeindename WHERE ortschaftsname IS NULL OR ortschaftsname = '';

ALTER TABLE swiss_location
    ALTER COLUMN ortschaftsname SET NOT NULL;

CREATE UNIQUE INDEX IF NOT EXISTS swiss_location_plz_ortschaft_unique
    ON swiss_location (plz4, ortschaftsname);

COMMENT ON COLUMN swiss_location.ortschaftsname IS
    'Post-Ortschaft (Adresse Ort) aus AMTOVZ — nicht die politische Gemeinde.';
COMMENT ON COLUMN swiss_location.gemeindename IS
    'Politische Gemeinde (BFS) mit dem höchsten Adressenanteil an dieser Ortschaft.';

